import numpy as np

def log_normal(X, mu, var):
    # X: (n,), mu, var: (k,) -> (n, k) 로그 밀도 log N(x; mu_j, var_j)
    return -0.5 * (np.log(2 * np.pi * var) + (X[:, None] - mu) ** 2 / var)

def logsumexp(A, axis):
    m = A.max(axis, keepdims=True)
    return (m + np.log(np.exp(A - m).sum(axis, keepdims=True))).squeeze(axis)

def gmm_loglik(X, phi, mu, var):
    # l = sum_i log sum_j phi_j N(x_i; mu_j, var_j)
    log_joint = np.log(phi) + log_normal(X, mu, var)   # (n, k) = log P(x_i, z_i=j)
    return logsumexp(log_joint, axis=1).sum()

def sample_gmm(n, phi, mu, var, rng):
    z = rng.choice(len(phi), size=n, p=phi)           # 동전(주사위)으로 출처 고르기
    return rng.normal(mu[z], np.sqrt(var[z])), z       # 그 출처의 가우시안에서 뽑기

rng = np.random.default_rng(0)
phi, mu, var = np.array([.6, .4]), np.array([0., 4.]), np.array([1., 1.])
X, z = sample_gmm(500, phi, mu, var, rng)
print(gmm_loglik(X, phi, mu, var))                   # 참 모수에서의 로그 우도
print(gmm_loglik(X, phi, np.array([1., 3.]), var))   # 틀린 평균이면 더 낮다
